        display: inline-flex;
        align-items: center;
        width: fit-content;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: #c2410c;
        font-size: 0.875rem;
        font-weight: 600;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 0;
        font-size: clamp(2.2rem, 5vw, 4.2rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
