      .subtitle {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .faq {
        display: grid;
        gap: 16px;
      }

      .example {
        overflow: hidden;
        border: 1px solid var(--panel-border);
        border-radius: 20px;
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(12px);
